```java
import java.util.*;
import java.util.stream.*;

public class Reduce {
    public static void main(String[] args) {
        List<Integer> xs = List.of(4, 1, 3);
        System.out.println(xs.stream().reduce(0, Integer::sum));           // 8
        System.out.println(Stream.<Integer>of().reduce(0, Integer::sum)); // 0

        List<String> words = List.of("apple", "avocado", "banana", "cherry", "blueberry");
        Map<Character, Long> byLetter = words.stream()
            .collect(Collectors.groupingBy(w -> w.charAt(0), TreeMap::new, Collectors.counting()));
        System.out.println(byLetter);                                     // {a=2, b=2, c=1}

        String csv = words.stream().filter(w -> w.length() > 5)
            .collect(Collectors.joining(","));
        System.out.println(csv);                                          // avocado,banana,cherry,blueberry
    }
}
